// This checks that tags close in the right order (like nesting boxes)
function isBalanced(html) {
  const stack = [];
  const re = /<\/?([a-zA-Z][a-zA-Z0-9]*)[^>]*>/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[1].toLowerCase();
    if (m[0].startsWith("</")) {
      if (stack.pop() !== tag) return false;
    } else if (!m[0].endsWith("/>")) {
      stack.push(tag);
    }
  }
  return stack.length === 0;
}
console.log(isBalanced("<p><b>hi</b></p>"));
console.log(isBalanced("<p><b>hi</p></b>"));

