// This checks a document string has all three skeleton parts
function validateDoc(html) {
  const missing = [];
  if (!html.includes("<!DOCTYPE html>")) missing.push("doctype");
  if (!html.includes("<head>")) missing.push("head");
  if (!html.includes("<body>")) missing.push("body");
  return missing.length === 0 ? "valid" : "missing: " + missing.join(", ");
}
console.log(validateDoc("<!DOCTYPE html><html><head></head><body></body></html>"));
console.log(validateDoc("<html><body></body></html>"));

